			/**
			 * 상담실별 예약 시간 필터링
			 */
			function filterCscAltmntPreconDataSet(){
			    
			    var cscList = app.lookup("dsCscSelectBoxList");
			    var cscAltmntRsvtList = app.lookup("dsCscAltmntRsvtList");
			    var cscAltmntPreconList = app.lookup("dsCscAltmntPreconList");
			    
			    
			    var cscEsntalNo = "";
			    var startTime = "";
			    var endTime = "";
			    
			    voColNameArray = [];
			    voColNameArray = cscAltmntPreconList.getColumnNames();
			    
			    for(var i = 0; i < cscAltmntRsvtList.getRowCount(); i ++ ){
			        
			        for(var j = 0; j < cscAltmntPreconList.getRowCount(); j ++ ){
			            
			            if(cscAltmntRsvtList.getValue(i, "CSC_ESNTAL_NO").toString() == cscAltmntPreconList.getValue(j, "CSC_ESNTAL_NO").toString()){
			                
			                cscEsntalNo = cscAltmntRsvtList.getValue(i, "CSC_ESNTAL_NO");
			                startTime = cscAltmntRsvtList.getValue(i, "RSVT_BGNG_HR");
			                endTime = cscAltmntRsvtList.getValue(i, "RSVT_END_HR");
			                
			                replaceCscAltmntPreconDataSet(cscEsntalNo, startTime, endTime);
			                
			            }
			        }
			    }
			}


			/**
			 * 시간별 예약현황 활성 데이터 가공
			 */
			function replaceCscAltmntPreconDataSet(cscEsntalNo, startTime, endTime){
			    
			    var cscAltmntPreconList = app.lookup("dsCscAltmntPreconList");
			    
			    for(var i = 0; i < voColNameArray.length; i ++ ){
			        
			        for(var j = 0; j < cscAltmntPreconList.getRowCount(); j ++ ){
			            
			            if(cscAltmntPreconList.getValue(j, "CSC_ESNTAL_NO").toString() == cscEsntalNo){
			                
			                if( voColNameArray[i].toString() != "CSC_ESNTAL_NO" && voColNameArray[i].toString() != "CSC_NM"){
			                
			                    if(Number(voColNameArray[i].toString().substring(1, 5)) >=startTime && Number(voColNameArray[i].toString().substring(1, 5)) <=endTime ){
			                        
			                        
			                        var chkStr = cscAltmntPreconList.getRow(j).getValue(voColNameArray[i]);
			                        
			                        cscAltmntPreconList.getRow(j).setValue(voColNameArray[i].toString(), "Y");
			                        
			                        
			                        
			                        if(chkStr.toString().substring(0, 1) == "S"){
			                            
			                            
			                            
			                        }else if(chkStr.toString().substring(0, 1) == "E"){
			                         
			                            var eEndTimeHourCheckValue = Number(chkStr.toString().substring(1, 3));
			                            var eEndTimeMinCheckValue = Number(chkStr.toString().substring(3, 5));
			                            
			                            var eEndTimeCheckValue = Number(chkStr.toString().substring(1, 5));
			                            
			                            var originEndTimeColumnName = "C" + chkStr.toString().substring(1, 5);
			                            var replaceEndTimeColumnName = "C" + eEndTimeCheckValue.toString();
			                            
			                            
			                            if(eEndTimeMinCheckValue == 0){
			                                replaceEndTimeColumnName = eEndTimeCheckValue-50;
			                            }else{
			                                replaceEndTimeColumnName = eEndTimeCheckValue-10;
			                            }// end if
			                            
			                            
			                            
			                            console.log("eEndTimeMinCheckValue : " + eEndTimeMinCheckValue);
			                            console.log("orign Endtime : " + originEndTimeColumnName);
			                            console.log("replace Endtime : " + replaceEndTimeColumnName);
			                            

			                            if(voColNameArray[i] == originEndTimeColumnName){
			                                
			                                console.log("if orign Endtime : " + originEndTimeColumnName);
			                                cscAltmntPreconList.getRow(j).setValue( originEndTimeColumnName, originEndTimeColumnName);
			                            }// end if
			                            
			                            
			                            if(voColNameArray[i] == replaceEndTimeColumnName){
			                                console.log("if replace Endtime : " + replaceEndTimeColumnName);
			                                cscAltmntPreconList.getRow(j).setValue( replaceEndTimeColumnName, "Y");
			                            }// end if
			                            
			                            
			                        }// end if
			                        
			                    }// end if
			                    
			                }// end if
			                
			            }// end if
			            
			        }// end for
			        
			    }// end for
			    
			   
			    app.lookup("dsCscAltmntPreconList").commit();
			    
			}





