			/**
			 * 예약시간 중복 체크
			 */
			function doRsvtHrDpcnCheck() {
			    
			    if(!validate()) return;
			    if(!validateRsvtTime()) return;
			    
			    // 예약시간 중복 체크 서브미션 호출
			    util.Submit.send(app, "subDpcn", function(pbSuccess) {
			        if (pbSuccess) {
			            
			            // 예약시간 중복 여부
			            var dmDpcnYn = "";
			            
			            
			            dmDpcnYn = util.DataMap.getValue(app, "dmDpcnYn", "DPCN_YN");
			            
			            if(dmDpcnYn == "Y"){
			                util.Msg.alert(app, "이미 예약되어있는 시간 입니다.");
			                return false;
			            }else if(dmDpcnYn == "N"){
			                doSave();
			            }
			            
			            
			        }
			    });
			}



			/**
			 * 필수 입력사항 체크
			 */
			function validate() {
			    
			        
			    // 데이터 변경사항이 없을시 "변경된 데이터가 없습니다" 출력
			    if (!util.FreeForm.isModified(app, "grpBoardDtl", "MSG")) return false;
			    
			    // 그룹 내 컬럼 유효성 체크
			    if (!util.validate(app, "grpBoardDtl")) return false;
			    
			    
			    
			    return true;
			}

			/**
			 * 사용시간 입력사항 체크
			 */
			function validateRsvtTime(){
			    
			    // 시간 09시 이전 20시 이상 선택시 밸리데이션 체크 > 후 데이터셋에 데이터 set
			    
			    var startHour = app.lookup("cmnTimeCombo1").startTime;
			    var startMinute = app.lookup("cmnTimeCombo1").startMinute;
			    
			    var endHour = app.lookup("cmnTimeCombo1").endTime;
			    var endMinute = app.lookup("cmnTimeCombo1").endMinute;
			    
			    
			    
			    if(startHour == "" || startMinute == "" || endHour == "" || endMinute == ""){
			        util.Msg.alert(app, "사용시간을 선택해주세요.");
			        return false;
			    }
			    
			    
			    
			    if(Number(startHour) < 9 || Number(startHour) > 20){
			        
			        util.Msg.alert(app, "사용 시작 시간은 오전 09시 00분 부터 오후 20시 50분 까지만 선택 하실 수 있습니다.");
			        return false;
			        
			    }
			    
			    
			    if(Number(endHour) < 9 || Number(endHour) > 21){
			        
			        
			        util.Msg.alert(app, "사용 종료 시간은 오전 09시 00분 부터 오후 21시 00분 까지만 선택 하실 수 있습니다.");
			        return false;
			    }
			    
			    
			    if(Number(endHour) == 21){
			            
			        if(Number(endMinute) > 0){
			            
			            util.Msg.alert(app, "21시 종료분 사용 시작 시간은 오전 09시 00분 부터 오후 21시 00분 까지만 선택 하실 수 있습니다.");
			            return false;
			    
			        }
			        
			    }
			    
			    
			    util.DataSet.setValue(app, "dsFrom", 0, "RSVT_BGNG_HR", startHour+startMinute);
			    util.DataSet.setValue(app, "dsFrom", 0, "RSVT_END_HR", endHour+endMinute);
			    
			    return true;
			    
			}




			/*
			 * 입력폼 시간 셋팅 바인딩안됨.
			 */
			function setRsvtTime(){
			    
			    
			    startHour = util.DataSet.getValue(app, "dsFrom", 0, "RSVT_BGNG_HR").toString().substring(0,2);
			    startMinute = util.DataSet.getValue(app, "dsFrom", 0, "RSVT_BGNG_HR").toString().substring(2,4);
			    
			    
			    app.lookup("cmnTimeCombo1").startTime = startHour;
			    app.lookup("cmnTimeCombo1").startMinute = startMinute;
			    
			    
			    endHour = util.DataSet.getValue(app, "dsFrom", 0, "RSVT_END_HR").toString().substring(0,2);
			    endMinute = util.DataSet.getValue(app, "dsFrom", 0, "RSVT_END_HR").toString().substring(2,4);
			        
			    
			    app.lookup("cmnTimeCombo1").endTime = endHour;
			    app.lookup("cmnTimeCombo1").endMinute = endMinute;
			    
			        
			}



