			/**
			 * CRUD 권한에 따른 화면 구성
			 ** @param {"CREATE" | "READ" | "UPDATE"} type 게시글 상세 조회 타입
			 */
			function setDtlCrud(type, taskwkSeCd) {
			    
			    if (type == "CREATE") {
			        
			        // 등록
			        
			        util.Control.setVisible(app, false, ["btnUpdate", "btnDelete", "btnRestore"]);
			        util.Control.setVisible(app, true, ["btnSave"]);
			        
			        util.Control.setReadOnly(app, false, "grpBoardDtl");
			        
			    } else if (type == "READ") {
			        
			        // 상세
			        
			        util.Control.setVisible(app, false, ["btnSave", "btnRestore"]);
			        util.Control.setVisible(app, true, ["btnUpdate", "btnDelete"]);
			        
			        // 시간 데이터 셋팅(바인딩 안됨.)
			        setRsvtTime();
			        
			        util.Control.setReadOnly(app, true, "grpBoardDtl");
			        
			    } else if (type == "UPDATE") {
			        
			        // 수정
			        
			        util.Control.setVisible(app, false, ["btnUpdate", "btnDelete"]);
			        util.Control.setVisible(app, true, ["btnSave", "btnRestore"]);
			        
			        util.Control.setReadOnly(app, false, "grpBoardDtl");
			        
			    }
			    
			}




			/**
			 * 상담실 목록 팝업 호출
			 */
			function openCscListPopup(type) {
			    
			    var voRowData = null;
			    
			    
			    
			    var initValue = {
			        taskwkSeCd: taskwkSeCd,
			        userId: userId,
			        instNo: instNo
			    }
			    
			    util.Dialog.open(app, "app/itgcms/syscmmn/schdlrsvtmng/cscaltmnt/CscListPop", popTitle, 940, 560, function( /*cpr.events.CUIEvent*/ e) {
			        
			        /*
			         * 다이얼로그 close 이벤트 핸들러(닫기 동작시 반환되는 값에 대한 처리)
			         * 다이얼로그가 이미 닫혀진 상태이기 때문에 다이얼로그 관련 이벤트리스너는 발생하지 않습니다.
			         */
			        /**@type cpr.controls.Dialog*/
			        var dialog = e.control;
			        var returnValue = dialog.returnValue;
			        
			        /*
			         * returnValue 처리
			         * returnValue가 단일값을 경우 그대로 사용할 수 있으며, JSON 데이터일 경우 key값을 통해 value를 받을 수 있습니다. 
			         */
			        if (!ValueUtil.isNull(returnValue)) {
			            // 상담실 목록 > 상담실 등록 저장한 경우  > 팝업 닫을시 상담실 select box 재조회
			            
			            if(returnValue == "save"){
			                viewType = "CREATE";
			                setDtlCrud(viewType, taskwkSeCd);
			                
			                selectedTabIndex = app.lookup("tab2").getSelectedTabItem().itemIndex;
			                
			                callSubMissionTypeData();
			            }
			            
			        }
			        
			        
			    }, initValue);
			}


