			/*
			 * 루트 컨테이너에서 load 이벤트 발생 시 호출.
			 * 앱이 최초 구성된후 최초 랜더링 직후에 발생하는 이벤트 입니다.
			 */
			function onBodyLoad( /* cpr.events.CEvent */ e) {
			    
			    
			    var paraCn = app.getAppProperty("PARA_CN");
			    console.log("paraCn", paraCn);
			    
			    /*공통 서비스 호출 (공통코드, 현재일자 등)*/
			    util.Submit.send(app, "subOnload", function(pbSuccess) {
			        if (pbSuccess) {
			            
			            // 서버 년월일 기본값 적용(현재년도)
			            vsSysDate = util.DataMap.getValue(app, "dmInitInfo", "SYS_DATE");
			            searchDate = vsSysDate;
			            
			            // 업무구분(해당업무 진입 메뉴 구분) > 변경될 수 있음. 정책 최종 확인 필요.
			            // 청소년상담복지센터(CYS-NET : U02), 학교밖청소년지원센터(꿈드림 : U03), 청소년쉼터(청소년쉼터 행정지원시스템 : U04)
			            taskwkSeCd = util.DataMap.getValue(app, "dmInitInfo", "TASKWK_SYS_SE_CD");
			            
			            if (taskwkSeCd == null || taskwkSeCd == "") {
			                
			                taskwkSeCd = "";
			            }
			            
			            // 사용자 아이디
			            userId = util.DataMap.getValue(app, "dmInitInfo", "USER_ID");
			            
			            // 기관번호
			            instNo = util.DataMap.getValue(app, "dmInitInfo", "INST_NO");
			            
			            
			            // 데이터 조회 현재년도 데이터맵 셋팅
			            util.DataMap.setValue(app, "dmSearchParam", "SEARCH_DATE", searchDate);
			            util.DataMap.setValue(app, "dmSearchParam", "DPCN_CHECK_TYPE", "I");
			            
			            // 사용시간 초기값 셋팅 
			            // 예약일자 기본값 적용(현재년도)
			            var insertRowData = {
			                RSVT_YMD: vsSysDate,
			                INST_NO: instNo,
			                USER_ID: userId,
			                TASKWK_SYS_SE_CD: taskwkSeCd,
			                REG_YMD: vsSysDate
			            }
			            
			            app.lookup("dsFrom").addRowData(insertRowData);
			            
			            viewType = "CREATE";
			            setDtlCrud(viewType, taskwkSeCd);
			            
			            setDtlTaskwkSeView();
			            
			            selectedTabIndex = app.lookup("tab2").getSelectedTabItem().itemIndex;
			            
			            callSubMissionTypeData();
			            
			            
			        }
			    });
			    
			}

